class Solution:
    def countUnivalSubtrees(self, root):
        if not root:
            return 0

        count = 0

        def dfs(node):
            nonlocal count
            if not node:
                return None  # empty subtree: no value to compare

            left = dfs(node.left)
            right = dfs(node.right)

            # A child is "compatible" if it's empty (None) or matches node.val
            if (left is None or left == node.val) and (right is None or right == node.val):
                count += 1
                return node.val
            return False  # sentinel distinct from any int value

        dfs(root)
        return count

class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        # XOR all numbers to get a ^ b
        xor_all = 0
        for num in nums:
            xor_all ^= num

        # Find the rightmost set bit in xor_all
        # This bit will be different between the two unique numbers
        rightmost_set_bit = xor_all & (-xor_all)

        # Partition numbers into two groups and XOR each group
        num1 = 0
        num2 = 0

        for num in nums:
            if num & rightmost_set_bit:
                # This bit is set
                num1 ^= num
            else:
                # This bit is not set
                num2 ^= num

        return [num1, num2]

class Solution:
    def nthUglyNumber(self, n: int) -> int:
        if n == 1:
            return 1
        ugly = [1] * n
        i2 = i3 = i5 = 0
        n2, n3, n5 = 2, 3, 5
        for i in range(1, n):
            nxt = n2 if n2 < n3 else n3
            if n5 < nxt:
                nxt = n5
            ugly[i] = nxt
            if nxt == n2:
                i2 += 1
                n2 = ugly[i2] * 2
            if nxt == n3:
                i3 += 1
                n3 = ugly[i3] * 3
            if nxt == n5:
                i5 += 1
                n5 = ugly[i5] * 5
        return ugly[n - 1]

class Solution:
    def minCostII(self, costs: List[List[int]]) -> int:
        if not costs:
            return 0

        n = len(costs)
        k = len(costs[0])

        dp = costs[0][:]
        INF = 10 ** 9

        for i in range(1, n):
            min1 = INF
            min2 = INF
            min1_idx = -1

            for j in range(k):
                v = dp[j]
                if v < min1:
                    min2 = min1
                    min1 = v
                    min1_idx = j
                elif v < min2:
                    min2 = v

            row = costs[i]
            dp = [
                row[j] + (min2 if j == min1_idx else min1)
                for j in range(k)
            ]

        return min(dp)

class Solution:
    def alienOrder(self, words: list[str]) -> str:
        # Collect all unique characters and build indegree in one pass
        indegree = {}
        for word in words:
            for c in word:
                indegree[c] = 0

        graph = {}
        n = len(words)

        for i in range(n - 1):
            w1 = words[i]
            w2 = words[i + 1]
            l1 = len(w1)
            l2 = len(w2)
            # Invalid: longer word is prefix of shorter word
            if l1 > l2 and w1[:l2] == w2:
                return ""

            # Find first differing character
            limit = l1 if l1 < l2 else l2
            j = 0
            while j < limit and w1[j] == w2[j]:
                j += 1
            if j < limit:
                c1 = w1[j]
                c2 = w2[j]
                # Only add edge if not already present (indegree check dedupes)
                adj = graph.get(c1)
                if adj is None:
                    graph[c1] = [c2]
                    indegree[c2] += 1
                elif c2 not in adj:
                    adj.append(c2)
                    indegree[c2] += 1

        # Topological sort using a stack (order doesn't matter)
        stack = [c for c, d in indegree.items() if d == 0]
        result = []
        total = len(indegree)

        while stack:
            c = stack.pop()
            result.append(c)
            adj = graph.get(c)
            if adj:
                for neighbor in adj:
                    d = indegree[neighbor] - 1
                    indegree[neighbor] = d
                    if d == 0:
                        stack.append(neighbor)

        if len(result) != total:
            return ""

        return "".join(result)

