class TreeNode:
    __slots__ = ('val', 'left', 'right')

    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    @staticmethod
    def fromList(lst):
        if not lst:
            return None
        root = TreeNode(lst[0])
        queue = [root]
        i = 1
        n = len(lst)
        head = 0
        while head < len(queue) and i < n:
            node = queue[head]
            head += 1
            if i < n and lst[i] is not None:
                node.left = TreeNode(lst[i])
                queue.append(node.left)
            i += 1
            if i < n and lst[i] is not None:
                node.right = TreeNode(lst[i])
                queue.append(node.right)
            i += 1
        return root


class Solution:
    def closestValue(self, root: TreeNode, target: float) -> int:
        closest = root.val
        best = closest - target
        if best < 0:
            best = -best
        while root:
            v = root.val
            diff = v - target
            if diff < 0:
                diff = -diff
            if diff < best or (diff == best and v < closest):
                best = diff
                closest = v
            root = root.left if target < v else root.right
        return closest

class Solution:
    def hIndex(self, citations: list[int]) -> int:
        # Sort citations in descending order
        citations.sort(reverse=True)

        # Find the maximum h-index
        h = 0
        for i, citation in enumerate(citations):
            if citation >= i + 1:
                h = i + 1
            else:
                break

        return h


