class Solution:
    def inorderSuccessor(self, root: TreeNode, p: TreeNode) -> TreeNode:
        successor = None
        pval = p.val
        while root:
            if pval < root.val:
                successor = root
                root = root.left
            else:
                root = root.right
        return successor

def build_tree_from_list(lst):
    if not lst or lst[0] is None:
        return None
    root = TreeNode(lst[0])
    queue = [root]
    i = 1
    n = len(lst)
    head = 0
    while head < len(queue) and i < n:
        node = queue[head]
        head += 1
        if i < n:
            v = lst[i]
            i += 1
            if v is not None:
                child = TreeNode(v)
                node.left = child
                queue.append(child)
        if i < n:
            v = lst[i]
            i += 1
            if v is not None:
                child = TreeNode(v)
                node.right = child
                queue.append(child)
    return root

class Solution:
    def removeInvalidParentheses(self, s: str):
        # Compute minimum removals needed
        left_remove = 0
        right_remove = 0
        for ch in s:
            if ch == '(':
                left_remove += 1
            elif ch == ')':
                if left_remove > 0:
                    left_remove -= 1
                else:
                    right_remove += 1

        result = set()
        n = len(s)

        def dfs(index, left_count, right_count, left_rem, right_rem, path):
            if index == n:
                if left_rem == 0 and right_rem == 0 and left_count == right_count:
                    result.add(''.join(path))
                return

            ch = s[index]

            if ch == '(':
                # Option 1: remove this '(' if budget allows
                if left_rem > 0:
                    dfs(index + 1, left_count, right_count, left_rem - 1, right_rem, path)
                # Option 2: keep this '('
                path.append(ch)
                dfs(index + 1, left_count + 1, right_count, left_rem, right_rem, path)
                path.pop()
            elif ch == ')':
                # Option 1: remove this ')' if budget allows
                if right_rem > 0:
                    dfs(index + 1, left_count, right_count, left_rem, right_rem - 1, path)
                # Option 2: keep this ')' only if it won't make prefix invalid
                if left_count > right_count:
                    path.append(ch)
                    dfs(index + 1, left_count, right_count + 1, left_rem, right_rem, path)
                    path.pop()
            else:
                path.append(ch)
                dfs(index + 1, left_count, right_count, left_rem, right_rem, path)
                path.pop()

        dfs(0, 0, 0, left_remove, right_remove, [])
        return list(result)
